from lib import *
S = SS('j284')
steps = [
    step("一次正常连接(Jetty 12.0.16 的 Jakarta WebSocket 服务端 + JDK 自带 java.net.http.WebSocket 客户端):@OnOpen(endpoint 实例 #1,默认 maxIdleTimeout = 30000 ms,maxTextMessageBufferSize = 65536)→ 两次 @OnMessage(都是实例 #1,都在 Jetty 的 qtp 线程上)→ 客户端 sendClose(1000, \"bye\") → 服务端 @OnClose(code = 1000 NORMAL_CLOSURE,reason = bye),客户端收到 close 回显。第二个连接得到一个新的 endpoint 实例 #2:每个连接一个 endpoint 实例,实例字段不要放跨连接共享的状态。", t=tl(S(1)), done=lidx(S(1), '实例 #1,session', '客户端(A) onOpen', '长度 5,内容 hello'), mark=lidx(S(1), '内容 again', 'sendClose(1000', 'code = 1000 (NORMAL_CLOSURE),reason = \"bye\"', 'endpoint 实例 #2', 'second-connection'), kv=KV([['回调顺序', '@OnOpen → @OnMessage × n → @OnClose'], ['endpoint 实例', '每个连接一个(#1、#2),在 Jetty qtp 线程上执行'], ['默认值', 'maxIdleTimeout 30000 ms,maxTextMessageBufferSize 65536']], ['endpoint 实例'])),
    step("几种异常关闭:客户端 abort()(不发 close 帧,直接断 TCP):服务端先 @OnError(ClosedChannelException)再 @OnClose(code = 1006 CLOSED_ABNORMALLY,reason = Session Closed)。服务端 @OnMessage 抛 IllegalStateException:@OnError 收到的是 CloseException(Endpoint notification error),不是原始异常;@OnClose 的 code = 1003(CANNOT_ACCEPT),客户端收到同样的 1003。session.setMaxIdleTimeout(800):空闲约 804 ms 后服务端 @OnError(WebSocketTimeoutException: Connection Idle Timeout),客户端收到 code = 1001(GOING_AWAY)。CloseReason 的 reason 超过 123 个 UTF-8 字节(200 个 x)抛 IllegalArgumentException。", t=tl(S(2)), done=lidx(S(2), '客户端(C)调用 abort()', 'ClosedChannelException', 'CLOSED_ABNORMALLY'), mark=lidx(S(2), '内容 boom', 'CloseException', 'CANNOT_ACCEPT', '空闲,从连接到被关闭用了约', 'WebSocketTimeoutException', 'Reason Phrase cannot exceed 123'), kv=KV([['客户端 abort()', '@OnError(ClosedChannelException) + @OnClose 1006'], ['@OnMessage 抛异常', '@OnError 收到 CloseException,@OnClose / 客户端 code 1003'], ['空闲超时', '804 ms 后 code 1001 GOING_AWAY'], ['reason > 123 字节', 'IllegalArgumentException']], ['@OnMessage 抛异常'])),
    step("消息大小限制:默认 maxTextMessageBufferSize = 65536,客户端发送 100,000 个字符的文本:服务端 @OnError(MessageTooLargeException: Text message too large: 69,592 > 65,536),连接以 code = 1009(TOO_BIG)关闭,客户端同样收到 1009;在 @OnOpen 里 session.setMaxTextMessageBufferSize(512 * 1024) 的 /ws/big 端点则正常收到 100000 字符并回复 ok:100000,之后正常关闭 1000。大消息要么调大限制,要么按帧分片处理。", t=tl(S(3)), done=lidx(S(3), '客户端(G) onOpen', 'Text message too large'), mark=lidx(S(3), 'TOO_BIG', '把 maxTextMessageBufferSize 调到 512 KiB', 'ok:100000'), kv=KV([['默认 65536,发 100,000 字符', '连接以 1009 TOO_BIG 关闭'], ['setMaxTextMessageBufferSize(512 KiB)', '正常收到,回复 ok:100000']], ['默认 65536,发 100,000 字符'])),
    step("并发发送:4 个线程各自对同一个 session 调用 getBasicRemote().sendText 500 次:在 Jetty 12 上成功 2000、失败 0(Jetty 自己串行化了写入);放进 synchronized (session) 成功 2000;getAsyncRemote().sendText 并发调用也是调用成功 2000、抛出异常 0,客户端最终收到 6000 条消息。JSR 356 规范没有保证并发发送安全(别的实现如 Tyrus 会在并发调用时抛 IllegalStateException),这里观察到的是 Jetty 的实现行为。", t=tl(S(4)), done=lidx(S(4), '服务端(send):4 个线程各自对同一个 session'), mark=lidx(S(4), 'synchronized (session)', 'getAsyncRemote', '实际收到的消息条数 6000'), kv=KV([['getBasicRemote 并发', 'Jetty 12 上 2000 / 2000 成功'], ['synchronized / getAsyncRemote', '同样全部成功'], ['客户端收到', '6000 条']], ['getBasicRemote 并发'])),
]
A = mkartj('j284', 284, 'Java,WebSocket,Jakarta WebSocket,Jetty,生命周期,关闭码,真实验证,动画演示',
    '用 Jetty 12.0.16 的 Jakarta WebSocket 服务端与 JDK 客户端实测 Endpoint 生命周期:每个连接一个实例,@OnOpen → @OnMessage → @OnClose;abort 得到 @OnError + 1006;@OnMessage 抛异常得到 CloseException 与 1003;空闲 804 ms 后 1001;100,000 字符超过默认 64 KiB 得到 1009;并发 sendText 在 Jetty 上不报错。',
    'WebSocket 的服务端 Endpoint 有几个回调,但连接是怎样结束的、关闭码是多少、@OnError 收到什么,常常只有在出问题时才知道。这篇用真实的连接,把正常关闭、断开、异常、空闲超时、消息过大和并发发送的行为逐个量出来。',
    [('1006 / 1003 / 1001 / 1009', 'abort、@OnMessage 抛异常、空闲超时、消息过大时服务端 @OnClose 的关闭码'), ('804 ms', 'setMaxIdleTimeout(800) 之后空闲连接被关闭的耗时(客户端收到 1001)'), ('2000 / 2000', '4 个线程并发 getBasicRemote().sendText 在 Jetty 12 上成功的次数(Tyrus 等实现可能抛异常)')],
    [('正常连接', None), ('异常关闭', None), ('消息大小', None), ('并发发送', None)],
    steps, [ENV_J + '。Jetty 12.0.16(jetty-ee10-websocket-jakarta-server)与 Jakarta WebSocket 2.1,客户端是 JDK 21 的 java.net.http.WebSocket;端口 9800;回调线程名被归一化为 qtp…-N;抽样的时间戳是单次运行', '没有验证:Tyrus / Tomcat 的 WebSocket 实现差异(尤其是并发发送与 @OnError 收到的异常)、TLS(wss)、子协议与扩展(permessage-deflate)、ping / pong 与 PongMessage、Spring WebSocket / STOMP、集群中的会话共享、背压(慢客户端)'], 'Jakarta WebSocket Endpoint 生命周期')
